-- Identity only: refreshed labelled public Amazon listing facts + matching stored supplier UPCs.
-- No prices, costs, stock, fees, eligibility or buying decisions are approved.
DO $$
DECLARE r record; o record; c record; master_id bigint;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"asin": "B0004LZUJQ", "sku": "KAID012", "ean": "0043000955673", "title": "Kool Aid Unsweetened Black Cherry 3.6g", "brand": "Kool-Aid", "variant": "Black Cherry", "unit_size": "3.6g", "case_qty": 48, "candidate_title": "Kool Aid Black Cherry Drink Sachet 3.6 g", "evidence": {"method": "public_labelled_review_batch2_2026_10_25", "amazon_upc": "043000955673", "amazon_sell_pack_qty": 1, "supplier_case_qty": 48, "supplier_offer_id": "463", "verifiedSupplierProductId": "KAID012", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B0004LZUJQ", "amazon_captured_at": "2026-10-25T22:52:39.814430+00:00", "amazon_labelled_facts": {"Brand Name": "Kraft", "Container Type": "Pouch", "Speciality": "Black Cherry\" or \"Cerise", "Number of Items": "1", "Unit Count": "3.6 gram", "UPC": "043000955673", "Sweetness Description": "Not Sweetened", "ASIN": "B0004LZUJQ", "Item Weight": "0.13 Ounces"}, "supplier_source": "https://sweetandglory.com/brands/i-m/kool-aid-wholesale-uk", "supplier_code_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Kraft is the manufacturer; Kool-Aid is the product brand. Single 3.6g unsweetened sachet, not prepared drink volume.", "commercial_approved": false}}, {"asin": "B000PYB7U8", "sku": "ICEB002", "ean": "0034000000982", "title": "Ice Breakers Sours 42g", "brand": "Ice Breakers", "variant": "Sours Watermelon Green Apple Tangerine", "unit_size": "42g", "case_qty": 8, "candidate_title": "Ice Breakers Sours, Sugar Free Mints, Watermelon, Green Apple, and Tangerine 42 g", "evidence": {"method": "public_labelled_review_batch2_2026_10_25", "amazon_upc": "034000000982", "amazon_sell_pack_qty": 1, "supplier_case_qty": 8, "supplier_offer_id": "154", "verifiedSupplierProductId": "ICEB002", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B000PYB7U8", "amazon_captured_at": "2026-10-25T22:52:44.879686+00:00", "amazon_labelled_facts": {"Brand Name": "Ice Breakers", "Container Type": "Packet", "UPC": "034000000982", "Set Name": "sugar free mint, watermelon, green apple and tangerine", "ASIN": "B000PYB7U8", "Unit Count": "42.0 gram", "Number of Items": "1", "Item Weight": "0.1 Pounds", "Item Package Quantity": "1", "Package Size Name": "1.5 Ounce", "Size": "Small"}, "supplier_source": "https://sweetandglory.com/brands/i-m/ice-breakers-wholesale-uk", "supplier_code_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Mixed Sours flavour established from full title and Set Name; do not replace with the truncated Apple metadata.", "commercial_approved": false}}, {"asin": "B01EY6Y3TO", "sku": "TACOB002", "ean": "0021000060627", "title": "Taco Bell Diablo Sauce 213g", "brand": "Taco Bell", "variant": "Diablo", "unit_size": "213g", "case_qty": 12, "candidate_title": "Taco Bell Diablo Sauce 213g", "evidence": {"method": "public_labelled_review_batch2_2026_10_25", "amazon_upc": "021000060627", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "746", "verifiedSupplierProductId": "TACOB002", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B01EY6Y3TO", "amazon_captured_at": "2026-10-25T22:52:44.549337+00:00", "amazon_labelled_facts": {"Brand Name": "Taco Bell", "Container Type": "Bottle", "UPC": "021000060627", "ASIN": "B01EY6Y3TO", "Item Weight": "0.47 Ounces", "Unit Count": "213.0 gram", "Number of Items": "1", "Package Size Name": "213g (Pack of 1)", "Size": "213 g (Pack of 1)"}, "supplier_source": "https://sweetandglory.com/brands/t-z/taco-bell-wholesale-uk", "supplier_code_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Identity size 213g agrees across title, unit count and pack size. Item Weight 0.47 Ounces is contradictory and must not be used for fees or shipping.", "commercial_approved": false}}, {"asin": "B079SKCVJK", "sku": "JBEL033L", "ean": "0071570004309", "title": "Jelly Belly Ice Cream Mix Jelly Beans 70g", "brand": "Jelly Belly", "variant": "Ice Cream Mix", "unit_size": "70g", "case_qty": 12, "candidate_title": "Jelly Belly,Ice Cream Mix Bag, 70g", "evidence": {"method": "public_labelled_review_batch2_2026_10_25", "amazon_upc": "071570004309", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "435", "verifiedSupplierProductId": "JBEL033L", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B079SKCVJK", "amazon_captured_at": "2026-10-25T22:52:46.314405+00:00", "amazon_labelled_facts": {"Brand Name": "Jelly Belly", "Container Type": "Bag", "UPC": "071570004309", "ASIN": "B079SKCVJK", "Unit Count": "70 gram", "Number of Items": "1", "Item Weight": "70 Grams", "Item Package Quantity": "1", "Package Size Name": "70g", "Size": "70 g (Pack of 1)"}, "supplier_source": "https://sweetandglory.com/brands/i-m/jelly-belly-wholesale-uk", "supplier_code_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Identity is Ice Cream Mix jelly beans in a bag. Generic Flavour Jelly,Peanut and Item Form Cream metadata are unreliable and are not canonical facts.", "commercial_approved": false}}, {"asin": "B00LZ2EBWK", "sku": "TWIZ012", "ean": "0034000544431", "title": "Twizzler Pull and Peel Cherry 172g", "brand": "Twizzlers", "variant": "Pull and Peel Cherry", "unit_size": "172g", "case_qty": 12, "candidate_title": "Twizzlers Cherry Pull-n-Peel Snack 6.1 Oz (172g)", "evidence": {"method": "public_labelled_review_batch2_2026_10_25", "amazon_upc": "034000544431", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "132", "verifiedSupplierProductId": "TWIZ012", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B00LZ2EBWK", "amazon_captured_at": "2026-10-25T22:53:08.493377+00:00", "amazon_labelled_facts": {"Brand Name": "Hershey''s", "Container Type": "Packet", "UPC": "034000544431", "ASIN": "B00LZ2EBWK", "Unit Count": "172 gram", "Number of Items": "1", "Item Weight": "172 Grams", "Item Package Quantity": "1", "Package Size Name": "172g", "Size": "172.9 g (Pack of 1)"}, "supplier_source": "https://sweetandglory.com/brands/t-z/twizzlers-wholesale-uk", "supplier_code_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Specific UPC 034000544431 identifies Cherry Pull N Peel 6.1oz in Hershey SmartLabel. 6.1oz converts to 172.934691g, explaining Amazon 172.9g versus 172g title/unit count/supplier label; specific equivalence only, no general tolerance change.", "commercial_approved": false, "manufacturer_reference": "https://smartlabel.hersheys.com/034000544431-0011-en-US/index.html"}}]'::jsonb) AS t(asin text,sku text,ean text,title text,brand text,variant text,unit_size text,case_qty integer,candidate_title text,evidence jsonb)
 LOOP
  SELECT so.*,s.name supplier INTO STRICT o FROM supplier_offers so JOIN suppliers s ON s.id=so.supplier_id WHERE s.name='Sweet & Glory' AND so.supplier_product_id=r.sku;
  SELECT * INTO STRICT c FROM amazon_catalogue_candidates WHERE asin=r.asin;
  IF c.title<>r.candidate_title OR o.product<>r.title THEN RAISE EXCEPTION 'Product description changed: %',r.asin; END IF;
  IF NOT o.is_active OR o.ean<>r.ean OR o.size<>r.unit_size OR o.case_qty<>r.case_qty THEN RAISE EXCEPTION 'Supplier evidence changed: %',r.asin; END IF;
  IF NOT EXISTS(SELECT 1 FROM unnest(ARRAY[c.ean,c.upc,c.gtin]) code WHERE lpad(code,14,'0')=lpad(r.ean,14,'0')) THEN RAISE EXCEPTION 'Amazon barcode changed: %',r.asin; END IF;
  IF c.match_status NOT IN ('unmatched','verified') OR (c.match_status='verified' AND coalesce(c.match_evidence->>'method','')<>'public_labelled_review_batch2_2026_10_25') THEN RAISE EXCEPTION 'Existing decision requires review: %',r.asin; END IF;
  IF (SELECT count(*) FROM master_product_identities WHERE asin=r.asin)>1 THEN RAISE EXCEPTION 'Duplicate masters: %',r.asin; END IF;
  SELECT id INTO master_id FROM master_product_identities WHERE asin=r.asin;
  IF master_id IS NULL THEN
   INSERT INTO master_product_identities(product_name,brand,variant,size,unit_size,ean,asin,status,canonical_key)
   VALUES(r.title,r.brand,r.variant,r.unit_size,r.unit_size,r.ean,r.asin,'verified',lower(r.brand||'|'||r.variant||'|'||r.unit_size)) RETURNING id INTO master_id;
  END IF;
  IF EXISTS(SELECT 1 FROM product_identity_offers WHERE supplier=o.supplier AND supplier_offer_id=r.sku AND identity_id<>master_id) OR EXISTS(SELECT 1 FROM amazon_product_listings WHERE marketplace='UK' AND asin=r.asin AND (identity_id<>master_id OR pack_qty<>1)) THEN RAISE EXCEPTION 'Conflicting saved relationship: %',r.asin; END IF;
  INSERT INTO product_identity_offers(identity_id,supplier,supplier_offer_id,match_score,match_status,match_reason)
  VALUES(master_id,o.supplier,r.sku,100,'verified','2026-10-25 evidence review: labelled Amazon UPC and supplier code agree; brand, product, size and single-unit sell pack checked from refreshed labelled public Amazon facts and stored supplier SKU. Supplier case is procurement quantity. No commercial approval.') ON CONFLICT(supplier,supplier_offer_id) DO NOTHING;
  INSERT INTO amazon_product_listings(identity_id,asin,ean,pack_qty,unit_size,title,marketplace,status)
  VALUES(master_id,r.asin,r.ean,1,r.unit_size,c.title,'UK','verified') ON CONFLICT(marketplace,asin) DO NOTHING;
  UPDATE amazon_catalogue_candidates SET match_status='verified',matched_master_identity_id=master_id,matched_supplier_offer_id=o.id,match_score=100,
   match_evidence=coalesce(match_evidence,'{}'::jsonb)||r.evidence,updated_at=now()
  WHERE asin=r.asin AND match_status='unmatched';
 END LOOP;
END $$;
